-- PostgreSQL baseline 001; preserves legacy text timestamp/JSON contracts.

-- _rowid explicitly preserves historical tie ordering during SQLite import.

CREATE TABLE "agent_actions" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "thread_id" TEXT NOT NULL,
  "payload" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "task_id" TEXT,
  "expires_at" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "agent_messages" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "thread_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "result" TEXT NOT NULL DEFAULT '{}',
  "client_key" TEXT,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("thread_id","client_key")
);

CREATE TABLE "agent_threads" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "application_events" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "application_id" TEXT NOT NULL,
  "from_status" TEXT NOT NULL,
  "to_status" TEXT NOT NULL,
  "note" TEXT NOT NULL DEFAULT '',
  "source_url" TEXT NOT NULL DEFAULT '',
  "document_id" TEXT NOT NULL DEFAULT '',
  "document_version" BIGINT NOT NULL DEFAULT 0,
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "application_snapshots" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "application_id" TEXT NOT NULL,
  "payload" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "applications" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "country" TEXT NOT NULL,
  "institution" TEXT NOT NULL,
  "program" TEXT NOT NULL,
  "intake" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Draft',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "submission_reference" TEXT NOT NULL DEFAULT '',
  "submitted_at" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id")
);

CREATE TABLE "assist_tokens" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "token_hash" TEXT NOT NULL,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "section_keys" TEXT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "revoked" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("token_hash")
);

CREATE TABLE "audit" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "actor_id" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "entity_type" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "summary" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "case_finance" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "person_id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "expected_fee" BIGINT NOT NULL DEFAULT 0,
  "upfront_fee" BIGINT NOT NULL DEFAULT 0,
  "incentive" BIGINT NOT NULL DEFAULT 0,
  "currency" TEXT NOT NULL DEFAULT 'PKR',
  "timeline" TEXT NOT NULL DEFAULT '',
  "revision" BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY ("person_id")
);

CREATE TABLE "crm_actions" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "payload" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "target_id" TEXT NOT NULL DEFAULT '',
  "expires_at" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "crm_messages" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "action_id" TEXT NOT NULL DEFAULT '',
  "client_key" TEXT,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("tenant_id","user_id","client_key")
);

CREATE TABLE "demo_migrations" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "name" TEXT,
  PRIMARY KEY ("name")
);

CREATE TABLE "document_versions" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "document_id" TEXT NOT NULL,
  "version" BIGINT NOT NULL,
  "original_name" TEXT NOT NULL,
  "stored_name" TEXT NOT NULL,
  "mime_type" TEXT NOT NULL,
  "byte_size" BIGINT NOT NULL,
  "sha256" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "source_path" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id"),
  UNIQUE ("document_id","version")
);

CREATE TABLE "documents" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "section_key" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'Received',
  "current_version" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "email_drafts" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "recipient" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Draft',
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "goals" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'Active',
  "target_date" TEXT NOT NULL DEFAULT '',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "import_items" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "run_id" TEXT NOT NULL,
  "source_path" TEXT NOT NULL,
  "document_id" TEXT,
  "status" TEXT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("run_id","source_path")
);

CREATE TABLE "import_runs" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "expected_count" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'In progress',
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "inquiry_limits" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "link_id" TEXT,
  "window_start" BIGINT NOT NULL,
  "count" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("link_id")
);

CREATE TABLE "inquiry_links" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "token_hash" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "revoked" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("token_hash")
);

CREATE TABLE "intake" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "section_key" TEXT NOT NULL,
  "data" TEXT NOT NULL DEFAULT '{}',
  "state" TEXT NOT NULL DEFAULT 'draft',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "updated_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("tenant_id","person_id","section_key")
);

CREATE TABLE "lead_followups" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "tenant_id" TEXT NOT NULL,
  "lead_id" TEXT NOT NULL,
  "follow_up" TEXT NOT NULL,
  "task_id" TEXT NOT NULL,
  PRIMARY KEY ("lead_id","follow_up")
);

CREATE TABLE "leads" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "phone" TEXT NOT NULL DEFAULT '',
  "source" TEXT NOT NULL DEFAULT 'Manual',
  "stage" TEXT NOT NULL DEFAULT 'New',
  "destination" TEXT NOT NULL DEFAULT '',
  "course" TEXT NOT NULL DEFAULT '',
  "notes" TEXT NOT NULL DEFAULT '',
  "follow_up" TEXT NOT NULL DEFAULT '',
  "timeline" TEXT NOT NULL DEFAULT '',
  "expected_fee" BIGINT NOT NULL DEFAULT 0,
  "upfront_fee" BIGINT NOT NULL DEFAULT 0,
  "incentive" BIGINT NOT NULL DEFAULT 0,
  "extras" TEXT NOT NULL DEFAULT '{}',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "person_id" TEXT,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "login_attempts" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "key" TEXT,
  "count" BIGINT NOT NULL,
  "window_start" BIGINT NOT NULL,
  PRIMARY KEY ("key")
);

CREATE TABLE "memberships" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "user_id" TEXT NOT NULL,
  "tenant_id" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "person_id" TEXT,
  PRIMARY KEY ("user_id","tenant_id")
);

CREATE TABLE "payments" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "amount" BIGINT NOT NULL,
  "reference" TEXT NOT NULL,
  "client_key" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("tenant_id","client_key"),
  CHECK (amount > 0)
);

CREATE TABLE "people" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "destination" TEXT NOT NULL DEFAULT '',
  "course" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'In progress',
  "initials" TEXT NOT NULL,
  "color" TEXT NOT NULL DEFAULT 'sage',
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "revision" BIGINT NOT NULL DEFAULT 1,
  "journey_stage" TEXT NOT NULL DEFAULT 'Planning',
  PRIMARY KEY ("id")
);

CREATE TABLE "projects" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'Active',
  "target_date" TEXT NOT NULL DEFAULT '',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "request_events" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "request_id" TEXT NOT NULL,
  "actor_id" TEXT NOT NULL,
  "event" TEXT NOT NULL,
  "note" TEXT NOT NULL DEFAULT '',
  "document_id" TEXT NOT NULL DEFAULT '',
  "document_version" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  PRIMARY KEY ("id")
);

CREATE TABLE "request_replies" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "request_id" TEXT NOT NULL,
  "actor_id" TEXT NOT NULL,
  "channel" TEXT NOT NULL,
  "message" TEXT NOT NULL,
  "client_key" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "timezone" TEXT NOT NULL,
  "proposal" TEXT NOT NULL DEFAULT '{}',
  "proposal_state" TEXT NOT NULL DEFAULT 'None',
  "request_revision" BIGINT NOT NULL,
  "document_id" TEXT NOT NULL DEFAULT '',
  "document_version" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  PRIMARY KEY ("id"),
  UNIQUE ("tenant_id","actor_id","client_key")
);

CREATE TABLE "requests" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT NOT NULL,
  "section_key" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "message" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Open',
  "created_by" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "revision" BIGINT NOT NULL DEFAULT 1,
  "requires_document" BIGINT NOT NULL DEFAULT 0,
  "follow_up_at" TEXT NOT NULL DEFAULT '',
  "follow_up_timezone" TEXT NOT NULL DEFAULT '',
  "follow_up_task_id" TEXT NOT NULL DEFAULT '',
  "document_id" TEXT NOT NULL DEFAULT '',
  "document_version" BIGINT NOT NULL DEFAULT 0,
  "review_note" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id")
);

CREATE TABLE "requirements" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "application_id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "section_key" TEXT NOT NULL DEFAULT '',
  "required" BIGINT NOT NULL DEFAULT 1,
  "status" TEXT NOT NULL DEFAULT 'Pending',
  "note" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "sessions" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "token_hash" TEXT,
  "user_id" TEXT NOT NULL,
  "tenant_id" TEXT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("token_hash")
);

CREATE TABLE "subscriptions" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "tenant_id" TEXT,
  "plan" TEXT NOT NULL DEFAULT 'Institute',
  "status" TEXT NOT NULL DEFAULT 'trial',
  "seats" BIGINT NOT NULL DEFAULT 5,
  "case_limit" BIGINT NOT NULL DEFAULT 100,
  "storage_mb" BIGINT NOT NULL DEFAULT 1024,
  "expires_at" TEXT NOT NULL DEFAULT '',
  "updated_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("tenant_id")
);

CREATE TABLE "task_events" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "task_id" TEXT NOT NULL,
  "event" TEXT NOT NULL,
  "from_stage" TEXT NOT NULL,
  "to_stage" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "project_id" TEXT NOT NULL,
  "project_title" TEXT NOT NULL,
  "goals_json" TEXT NOT NULL DEFAULT '[]',
  "actor_id" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  PRIMARY KEY ("id")
);

CREATE TABLE "task_goals" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "tenant_id" TEXT NOT NULL,
  "task_id" TEXT NOT NULL,
  "goal_id" TEXT NOT NULL,
  PRIMARY KEY ("task_id","goal_id")
);

CREATE TABLE "task_reminders" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "task_id" TEXT NOT NULL,
  "remind_at" TEXT NOT NULL,
  "timezone" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'scheduled',
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "tasks" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "person_id" TEXT,
  "title" TEXT NOT NULL,
  "stage" TEXT NOT NULL DEFAULT 'To do',
  "important" BIGINT NOT NULL DEFAULT 0,
  "urgent" BIGINT NOT NULL DEFAULT 0,
  "due_date" TEXT NOT NULL DEFAULT '',
  "assignee" TEXT NOT NULL DEFAULT '',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "project_id" TEXT NOT NULL DEFAULT '',
  "completed_at" TEXT,
  "last_actor_id" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id")
);

CREATE TABLE "tenants" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "name" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE "update_inbox" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "tenant_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "sender" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "source_at" TEXT NOT NULL,
  "source_message_id" TEXT NOT NULL DEFAULT '',
  "source_url" TEXT NOT NULL DEFAULT '',
  "fingerprint" TEXT NOT NULL,
  "client_key" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Pending',
  "revision" BIGINT NOT NULL DEFAULT 1,
  "review" TEXT NOT NULL DEFAULT '{}',
  "review_expires_at" BIGINT NOT NULL DEFAULT 0,
  "decision_note" TEXT NOT NULL DEFAULT '',
  "applied_at" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  PRIMARY KEY ("id"),
  UNIQUE ("tenant_id","user_id","fingerprint"),
  UNIQUE ("tenant_id","user_id","client_key")
);

CREATE TABLE "users" (
  "_rowid" BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "id" TEXT,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "password_hash" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);

ALTER TABLE "agent_actions" ADD CONSTRAINT "agent_actions_fk_0" FOREIGN KEY ("thread_id") REFERENCES "agent_threads" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "agent_messages" ADD CONSTRAINT "agent_messages_fk_0" FOREIGN KEY ("thread_id") REFERENCES "agent_threads" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "applications" ADD CONSTRAINT "applications_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "case_finance" ADD CONSTRAINT "case_finance_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_fk_0" FOREIGN KEY ("document_id") REFERENCES "documents" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "documents" ADD CONSTRAINT "documents_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inquiry_links" ADD CONSTRAINT "inquiry_links_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "intake" ADD CONSTRAINT "intake_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "leads" ADD CONSTRAINT "leads_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "memberships" ADD CONSTRAINT "memberships_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "memberships" ADD CONSTRAINT "memberships_fk_1" FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payments" ADD CONSTRAINT "payments_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "people" ADD CONSTRAINT "people_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "requests" ADD CONSTRAINT "requests_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "task_reminders" ADD CONSTRAINT "task_reminders_fk_0" FOREIGN KEY ("task_id") REFERENCES "tasks" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tasks" ADD CONSTRAINT "tasks_fk_0" FOREIGN KEY ("person_id") REFERENCES "people" ("id") DEFERRABLE INITIALLY IMMEDIATE;

CREATE INDEX idx_people_tenant ON people(tenant_id);

CREATE INDEX idx_tasks_tenant ON tasks(tenant_id);

CREATE INDEX idx_documents_tenant ON documents(tenant_id);

